import pandas as pd
with open('summary.txt') as f: print(f.read())
t=pd.read_csv('table.csv'); print(t.shape); print(t.groupby('Region').size())
src=open('chart.py').read(); ns={}
exec(src.split('rows = []')[0], ns)
d=ns['data']; P=ns['policy_programs']
for metset in [['Funding','Impact','Satisfaction'],['Funding','Impact','Satisfaction','Implementation']]:
    mism=0
    for (r,p),g in t.groupby(['Region','Policy Program']):
        i=P.index(p); a=sorted(g.Value); b=sorted(d[r][m][i] for m in metset)
        if a!=b: mism+=1; 
    print(metset, 'mismatches',mism)
for (r,p),g in list(t.groupby(['Region','Policy Program']))[:6]:
    i=P.index(p); print(r,p,list(g.Value),[d[r][m][i] for m in d[r]])
